import { MongoClient } from "mongodb";
import { log, safeErr } from "./logger.js";

let client = null;
let db = null;

export async function connectMongo(uri) {
  if (db) return db;

  try {
    client = new MongoClient(uri, {
      maxPoolSize: 10,
      ignoreUndefined: true,
    });

    await client.connect();
    db = client.db();
    log.info("db.connected", { mongodbUriSet: Boolean(uri) });
    await ensureIndexes();
    return db;
  } catch (err) {
    log.error("db.connect.failure", { err: safeErr(err) });
    throw err;
  }
}

export function getDb() {
  if (!db) throw new Error("MongoDB is not connected");
  return db;
}

export async function closeMongo() {
  if (!client) return;
  await client.close();
  client = null;
  db = null;
  log.info("db.closed");
}

async function createIndex(collectionName, key, options = {}) {
  try {
    await getDb().collection(collectionName).createIndex(key, options);
  } catch (err) {
    log.error("db.index.failure", {
      collection: collectionName,
      operation: "createIndex",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function ensureIndexes() {
  await createIndex("users", { telegramUserId: 1 }, { unique: true });
  await createIndex("watchlists", { telegramUserId: 1, coinId: 1 }, { unique: true });
  await createIndex("watchlists", { telegramUserId: 1 });
  await createIndex("alerts", { status: 1, coinId: 1 });
  await createIndex("alerts", { telegramUserId: 1, status: 1 });
  await createIndex("alerts", { active: 1, coinId: 1 });
  await createIndex("alert_events", { alertId: 1, createdAt: -1 });
}

alertService.js.content:
import { ObjectId } from "mongodb";
import { getDb } from "../lib/mongo.js";
import { log, safeErr } from "../lib/logger.js";
import { getPricesByCoinIds } from "./priceService.js";
import { formatUsd } from "../utils/format.js";

const ALERT_POLL_INTERVAL_MS = 60000;
const MAX_ACTIVE_ALERTS_PER_USER = 50;
let running = false;
let stopped = false;
let timer = null;
let lastMemoryLogAt = 0;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function toObjectId(id) {
  try {
    return new ObjectId(String(id));
  } catch {
    return null;
  }
}

export async function createAlert({ telegramUserId, chatId, coin, direction, targetPrice }) {
  const normalizedDirection = String(direction || "").toLowerCase();
  const price = Number(targetPrice);

  if (!["above", "below"].includes(normalizedDirection)) {
    return { ok: false, reason: "direction" };
  }

  if (!Number.isFinite(price) || price <= 0) {
    return { ok: false, reason: "price" };
  }

  try {
    const activeCount = await getDb().collection("alerts").countDocuments({ telegramUserId, status: "active" });
    if (activeCount >= MAX_ACTIVE_ALERTS_PER_USER) {
      return { ok: false, reason: "limit" };
    }

    const now = new Date();
    const doc = {
      telegramUserId,
      chatId: String(chatId),
      coinId: coin.id,
      symbol: coin.symbol,
      name: coin.name,
      direction: normalizedDirection,
      targetPrice: price,
      active: true,
      status: "active",
      triggeredAt: null,
      lastCheckedAt: null,
      lastObservedPrice: null,
      notificationStatus: "pending",
      createdAt: now,
      updatedAt: now,
    };

    const result = await getDb().collection("alerts").insertOne(doc);
    return { ok: true, alertId: String(result.insertedId), alert: { ...doc, _id: result.insertedId } };
  } catch (err) {
    log.error("db.write.failure", {
      collection: "alerts",
      operation: "insertOne",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function listUserAlerts({ telegramUserId }) {
  try {
    return await getDb()
      .collection("alerts")
      .find({ telegramUserId, status: "active" })
      .sort({ createdAt: -1 })
      .toArray();
  } catch (err) {
    log.error("db.read.failure", {
      collection: "alerts",
      operation: "find",
      err: safeErr(err),
    });
    throw err;
  }
}

export async function removeAlert({ telegramUserId, alertId }) {
  const _id = toObjectId(alertId);
  if (!_id) return { ok: false, reason: "invalid" };

  try {
    const result = await getDb().collection("alerts").updateOne(
      { _id, telegramUserId, status: "active" },
      {
        $set: {
          active: false,
          status: "removed",
          updatedAt: new Date(),
        },
      }
    );

    if (result.matchedCount === 0) return { ok: false, reason: "missing" };
    return { ok: true };
  } catch (err) {
    log.error("db.write.failure", {
      collection: "alerts",
      operation: "updateOne.remove",
      err: safeErr(err),
    });
    throw err;
  }
}

async function getActiveAlerts() {
  try {
    return await getDb()
      .collection("alerts")
      .find({ status: "active", active: true })
      .limit(2000)
      .toArray();
  } catch (err) {
    log.error("db.read.failure", {
      collection: "alerts",
      operation: "find.active",
      err: safeErr(err),
    });
    throw err;
  }
}

async function markTriggered(alert, currentPrice) {
  const now = new Date();

  try {
    const result = await getDb().collection("alerts").updateOne(
      { _id: alert._id, status: "active", active: true },
      {
        $set: {
          active: false,
          status: "triggered",
          triggeredAt: now,
          lastCheckedAt: now,
          lastObservedPrice: currentPrice,
          triggerPrice: currentPrice,
          notificationStatus: "sending",
          updatedAt: now,
        },
      }
    );

    if (result.modifiedCount !== 1) return false;

    await getDb().collection("alert_events").insertOne({
      alertId: String(alert._id),
      telegramUserId: alert.telegramUserId,
      coinId: alert.coinId,
      symbol: alert.symbol,
      direction: alert.direction,
      targetPrice: alert.targetPrice,
      observedPrice: currentPrice,
      eventType: "triggered",
      createdAt: now,
    });

    return true;
  } catch (err) {
    log.error("db.write.failure", {
      collection: "alerts",
      operation: "updateOne.trigger",
      err: safeErr(err),
    });
    throw err;
  }
}

async function updateNotificationStatus(alertId, status, err = "") {
  try {
    await getDb().collection("alerts").updateOne(
      { _id: alertId },
      {
        $set: {
          notificationStatus: status,
          notificationError: String(err || "").slice(0, 500),
          updatedAt: new Date(),
        },
      }
    );
  } catch (dbErr) {
    log.error("db.write.failure", {
      collection: "alerts",
      operation: "updateOne.notificationStatus",
      err: safeErr(dbErr),
    });
  }
}

function conditionMet(alert, currentPrice) {
  if (alert.direction === "above") return currentPrice >= Number(alert.targetPrice);
  if (alert.direction === "below") return currentPrice <= Number(alert.targetPrice);
  return false;
}

async function notify(api, alert, currentPrice) {
  const text = [
    "Crypto price alert triggered",
    `${String(alert.symbol).toUpperCase()} is now ${formatUsd(currentPrice)}`,
    `Condition: ${alert.direction} ${formatUsd(alert.targetPrice)}`,
    `Alert ID: ${String(alert._id)}`,
  ].join("\n");

  try {
    await api.sendMessage(alert.chatId, text);
    await updateNotificationStatus(alert._id, "sent");
  } catch (err) {
    log.error("telegram.send.failure", {
      feature: "alert_notification",
      alertId: String(alert._id),
      err: safeErr(err),
    });
    await updateNotificationStatus(alert._id, "failed", safeErr(err));
  }
}

async function runCycle(api) {
  log.info("alerts.poll.cycle");

  const now = Date.now();
  if (now - lastMemoryLogAt > 60000) {
    const m = process.memoryUsage();
    log.info("mem", {
      rssMB: Math.round(m.rss / 1e6),
      heapUsedMB: Math.round(m.heapUsed / 1e6),
    });
    lastMemoryLogAt = now;
  }

  const alerts = await getActiveAlerts();
  if (alerts.length === 0) return;

  const coinIds = [...new Set(alerts.map((alert) => alert.coinId).filter(Boolean))];
  let prices;

  try {
    prices = await getPricesByCoinIds(coinIds);
  } catch (err) {
    log.warn("alerts.poll.price_failure", { err: safeErr(err) });
    return;
  }

  for (const alert of alerts) {
    const price = prices.get(alert.coinId);
    if (!price || price.stale) continue;

    const currentPrice = Number(price.usd);
    if (!Number.isFinite(currentPrice)) continue;

    try {
      await getDb().collection("alerts").updateOne(
        { _id: alert._id, status: "active", active: true },
        {
          $set: {
            lastCheckedAt: new Date(),
            lastObservedPrice: currentPrice,
            updatedAt: new Date(),
          },
        }
      );

      if (!conditionMet(alert, currentPrice)) continue;

      const claimed = await markTriggered(alert, currentPrice);
      if (!claimed) continue;
      await notify(api, alert, currentPrice);
    } catch (err) {
      log.error("alerts.poll.alert_failure", {
        alertId: String(alert._id),
        err: safeErr(err),
      });
    }
  }
}

export function startAlertPolling(api) {
  if (running) return;
  running = true;
  stopped = false;
  log.info("alerts.poll.start", { intervalMs: ALERT_POLL_INTERVAL_MS });

  const loop = async () => {
    while (!stopped) {
      try {
        await runCycle(api);
      } catch (err) {
        log.error("alerts.poll.failure", { err: safeErr(err) });
      }

      if (!stopped) await sleep(ALERT_POLL_INTERVAL_MS);
    }
  };

  timer = loop();
}

export async function stopAlertPolling() {
  stopped = true;
  running = false;
  await timer;
  timer = null;
}

priceService.js.content:
import { log, safeErr } from "../lib/logger.js";
import { normalizeSymbol } from "../utils/format.js";

const COINGECKO_BASE = "https://api.coingecko.com/api/v3";
const COIN_LIST_TTL_MS = 12 * 60 * 60 * 1000;
const PRICE_TTL_MS = 45 * 1000;
const STALE_PRICE_TTL_MS = 10 * 60 * 1000;
const REQUEST_TIMEOUT_MS = 10000;

const knownIds = new Map([
  ["btc", { id: "bitcoin", symbol: "btc", name: "Bitcoin" }],
  ["eth", { id: "ethereum", symbol: "eth", name: "Ethereum" }],
  ["sol", { id: "solana", symbol: "sol", name: "Solana" }],
  ["bnb", { id: "binancecoin", symbol: "bnb", name: "BNB" }],
  ["xrp", { id: "ripple", symbol: "xrp", name: "XRP" }],
  ["ada", { id: "cardano", symbol: "ada", name: "Cardano" }],
  ["doge", { id: "dogecoin", symbol: "doge", name: "Dogecoin" }],
  ["matic", { id: "matic-network", symbol: "matic", name: "Polygon" }],
  ["pol", { id: "polygon-ecosystem-token", symbol: "pol", name: "Polygon Ecosystem Token" }],
  ["usdt", { id: "tether", symbol: "usdt", name: "Tether" }],
  ["usdc", { id: "usd-coin", symbol: "usdc", name: "USDC" }],
]);

let coinListCache = {
  data: null,
  expiresAt: 0,
};

const priceCache = new Map();

export class SymbolNotFoundError extends Error {
  constructor(symbol) {
    super(`Unknown symbol: ${symbol}`);
    this.name = "SymbolNotFoundError";
    this.symbol = symbol;
  }
}

export class SymbolAmbiguousError extends Error {
  constructor(symbol, options) {
    super(`Ambiguous symbol: ${symbol}`);
    this.name = "SymbolAmbiguousError";
    this.symbol = symbol;
    this.options = options;
  }
}

function withTimeout(ms = REQUEST_TIMEOUT_MS) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), ms);
  return { signal: ctrl.signal, clear: () => clearTimeout(timer) };
}

async function fetchJson(url, feature) {
  const { signal, clear } = withTimeout();
  const started = Date.now();

  try {
    log.info("price.api.start", { provider: "coingecko", feature });
    const res = await fetch(url, {
      headers: { accept: "application/json" },
      signal,
    });

    if (!res.ok) {
      throw new Error(`CoinGecko HTTP ${res.status}`);
    }

    const json = await res.json();
    log.info("price.api.success", {
      provider: "coingecko",
      feature,
      ms: Date.now() - started,
    });
    return json;
  } catch (err) {
    log.warn("price.api.failure", {
      provider: "coingecko",
      feature,
      err: safeErr(err),
    });
    throw err;
  } finally {
    clear();
  }
}

export async function getCoinList() {
  const now = Date.now();
  if (coinListCache.data && coinListCache.expiresAt > now) return coinListCache.data;

  const json = await fetchJson(`${COINGECKO_BASE}/coins/list?include_platform=false`, "coin_list");
  coinListCache = {
    data: Array.isArray(json) ? json : [],
    expiresAt: now + COIN_LIST_TTL_MS,
  };
  return coinListCache.data;
}

export async function resolveCoin(input) {
  const symbol = normalizeSymbol(input);
  if (!symbol) throw new SymbolNotFoundError(symbol);

  const known = knownIds.get(symbol);
  if (known) return known;

  const list = await getCoinList();
  const matches = list.filter((coin) => String(coin.symbol || "").toLowerCase() === symbol);

  if (matches.length === 0) throw new SymbolNotFoundError(symbol);

  const exactId = matches.find((coin) => String(coin.id || "").toLowerCase() === symbol);
  if (exactId) return exactId;

  if (matches.length === 1) return matches[0];

  const shortOptions = matches.slice(0, 5).map((coin) => ({
    id: coin.id,
    symbol: coin.symbol,
    name: coin.name,
  }));

  throw new SymbolAmbiguousError(symbol, shortOptions);
}

function freshCachedPrice(coinId) {
  const cached = priceCache.get(coinId);
  if (!cached) return null;
  if (cached.expiresAt > Date.now()) return { ...cached.value, stale: false };
  return null;
}

function staleCachedPrice(coinId) {
  const cached = priceCache.get(coinId);
  if (!cached) return null;
  if (cached.staleExpiresAt > Date.now()) return { ...cached.value, stale: true };
  return null;
}

function setCachedPrice(coinId, price) {
  priceCache.set(coinId, {
    value: price,
    expiresAt: Date.now() + PRICE_TTL_MS,
    staleExpiresAt: Date.now() + STALE_PRICE_TTL_MS,
  });
}

export async function getPriceByCoinId(coinId) {
  const fresh = freshCachedPrice(coinId);
  if (fresh) return fresh;

  const url = `${COINGECKO_BASE}/simple/price?ids=${encodeURIComponent(coinId)}&vs_currencies=usd&include_24hr_change=true`;

  try {
    const json = await fetchJson(url, "simple_price");
    const row = json?.[coinId];
    if (!row || !Number.isFinite(Number(row.usd))) {
      throw new Error("CoinGecko returned no USD price");
    }

    const price = {
      coinId,
      usd: Number(row.usd),
      usd24hChange: Number(row.usd_24h_change),
      fetchedAt: new Date(),
      stale: false,
    };

    setCachedPrice(coinId, price);
    return price;
  } catch (err) {
    const stale = staleCachedPrice(coinId);
    if (stale) return stale;
    throw err;
  }
}

export async function getPricesByCoinIds(coinIds) {
  const uniqueIds = [...new Set(coinIds.filter(Boolean))];
  const output = new Map();
  const missing = [];

  for (const coinId of uniqueIds) {
    const fresh = freshCachedPrice(coinId);
    if (fresh) output.set(coinId, fresh);
    else missing.push(coinId);
  }

  if (missing.length === 0) return output;

  const url = `${COINGECKO_BASE}/simple/price?ids=${encodeURIComponent(missing.join(","))}&vs_currencies=usd&include_24hr_change=true`;

  try {
    const json = await fetchJson(url, "batch_price");

    for (const coinId of missing) {
      const row = json?.[coinId];
      if (!row || !Number.isFinite(Number(row.usd))) continue;

      const price = {
        coinId,
        usd: Number(row.usd),
        usd24hChange: Number(row.usd_24h_change),
        fetchedAt: new Date(),
        stale: false,
      };

      setCachedPrice(coinId, price);
      output.set(coinId, price);
    }
  } catch (err) {
    for (const coinId of missing) {
      const stale = staleCachedPrice(coinId);
      if (stale) output.set(coinId, stale);
    }

    if (output.size === 0) throw err;
  }

  return output;
}

export async function getPriceForSymbol(symbol) {
  const coin = await resolveCoin(symbol);
  const price = await getPriceByCoinId(coin.id);
  return { coin, price };
}

